      "cites": ["ts-seat-service-M0001"]
    },
    {
      "category": "config_regression",
      "service": "ts-travel-service",
      "why_less_likely": "No configuration change or deployment events are recorded in the operations log for ts-travel-service during the window.",
      "cites": []
    },
